import{_ as s,o as l,c,ah as d}from"./chunks/framework.BcMkjLiY.js";const g="/projects/TonyPi/en/latest/assets/image3.DvEXvALf.jpg",h="/projects/TonyPi/en/latest/assets/image4.BGIIj1iQ.jpeg",p="/projects/TonyPi/en/latest/assets/image5.CCgHJijY.jpeg",o="/projects/TonyPi/en/latest/assets/image6.D0H3u9si.jpeg",n="/projects/TonyPi/en/latest/assets/image7.DU5uGdZJ.jpeg",m="data:image/png;base64,",u="/projects/TonyPi/en/latest/assets/image9.CCsdwR2I.jpg",A="/projects/TonyPi/en/latest/assets/image10.BrS8dW-V.jpg",b="/projects/TonyPi/en/latest/assets/image11.D7c4J9S8.jpeg",f="/projects/TonyPi/en/latest/assets/image3.DvEXvALf.jpg",y="/projects/TonyPi/en/latest/assets/image13.vpkmvaJ5.jpg",P="/projects/TonyPi/en/latest/assets/image14.CXCN6_-U.jpg",v="/projects/TonyPi/en/latest/assets/image15.CDTFHcCk.jpg",w="/projects/TonyPi/en/latest/assets/image18.WN0LS2tF.jpg",q="/projects/TonyPi/en/latest/assets/image19.gLWIur7E.jpg",T="/projects/TonyPi/en/latest/assets/image20.vlh4c-n2.jpg",k="/projects/TonyPi/en/latest/assets/image10.BrS8dW-V.jpg",z="/projects/TonyPi/en/latest/assets/image2.S3_ZbhF7.png",j="/projects/TonyPi/en/latest/assets/image3.Cy3Ye87j.png",C="/projects/TonyPi/en/latest/assets/image21.D6IGORkK.png",I="/projects/TonyPi/en/latest/assets/image5.DlXJLnnp.png",x="/projects/TonyPi/en/latest/assets/image6.DRJzeJ3Z.png",_="/projects/TonyPi/en/latest/assets/image7.BcIUOmod.png",t="/projects/TonyPi/en/latest/assets/image24.BznAmNjP.png",Q="/projects/TonyPi/en/latest/assets/image9.BxSJkIE8.png",S="/projects/TonyPi/en/latest/assets/image10.BVe4Tz09.png",E="/projects/TonyPi/en/latest/assets/image11.ChAdg_RO.png",R="/projects/TonyPi/en/latest/assets/image13.B8zM1s26.png",W="/projects/TonyPi/en/latest/assets/image14.-fZ_fPEt.png",B="/projects/TonyPi/en/latest/assets/image15.DDZ6HZBo.png",V="/projects/TonyPi/en/latest/assets/image17.c-T3u-nt.png",L="/projects/TonyPi/en/latest/assets/image26.BqRxzcZn.png",D="/projects/TonyPi/en/latest/assets/image18.BnXOYPNr.png",G="/projects/TonyPi/en/latest/assets/image16.B61GMSjE.png",i="/projects/TonyPi/en/latest/assets/image20.C30YgCzc.png",O="/projects/TonyPi/en/latest/assets/image12.Ctex-NV0.png",U="/projects/TonyPi/en/latest/assets/image23.C285ZNUp.png",a="data:image/png;base64,",N="/projects/TonyPi/en/latest/assets/image25.DM1c56bo.png",Z="/projects/TonyPi/en/latest/assets/image2.BtjdiD-g.jpeg",F="/projects/TonyPi/en/latest/assets/image3.BcuPvefK.png",r="/projects/TonyPi/en/latest/assets/image4.DmDGm4l9.png",Y="/projects/TonyPi/en/latest/assets/image5.HWZC2QW9.png",H="/projects/TonyPi/en/latest/assets/image6.svCLMSQe.png",M="/projects/TonyPi/en/latest/assets/image7.BbugTGTC.png",J="/projects/TonyPi/en/latest/assets/image10.DxQMThBQ.png",K="/projects/TonyPi/en/latest/assets/image11.-S1p6HP9.png",X="/projects/TonyPi/en/latest/assets/image12.ClLttV6c.png",$="/projects/TonyPi/en/latest/assets/image13.Bcpr3aj1.png",tt="/projects/TonyPi/en/latest/assets/image14.CEuj1CU_.png",et="/projects/TonyPi/en/latest/assets/image15.BnWiSzTs.png",ot="data:image/png;base64,",nt="/projects/TonyPi/en/latest/assets/image17.BkvGuCiv.png",it="data:image/png;base64,",at="/projects/TonyPi/en/latest/assets/image19.CUlRe7BJ.png",rt="/projects/TonyPi/en/latest/assets/image20.Dsz6Cz8f.png",st="/projects/TonyPi/en/latest/assets/image21.BtQhasHW.png",lt="/projects/TonyPi/en/latest/assets/image22.mP2-qF-l.png",ct="/projects/TonyPi/en/latest/assets/image23.CcdC4yDc.png",dt="/projects/TonyPi/en/latest/assets/image24.BZ5f2PnW.png",gt="/projects/TonyPi/en/latest/assets/image25.CSqj5NaW.png",ht="/projects/TonyPi/en/latest/assets/image25.CSqj5NaW.png",vt=JSON.parse('{"title":"2. Quick User Experience","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2.quick_user_experience.md","filePath":"docs/2.quick_user_experience.md"}'),pt={name:"docs/2.quick_user_experience.md"};function mt(ut,e,At,bt,ft,yt){return l(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="_2-quick-user-experience" tabindex="-1">2. Quick User Experience <a class="header-anchor" href="#_2-quick-user-experience" aria-label="Permalink to &quot;2. Quick User Experience&quot;">​</a></h1><p id="anchor_1"></p><h2 id="_2-1-app-installation-and-connection" tabindex="-1">2.1 APP Installation and Connection <a class="header-anchor" href="#_2-1-app-installation-and-connection" aria-label="Permalink to &quot;2.1 APP Installation and Connection&quot;">​</a></h2><p id="anchor_2"></p><p>The following instructions use TurboPi as an example and apply to other Hiwonder Raspberry Pi series products as well. In this section, you will learn how to use APP &quot;<strong>WonderPi</strong>&quot; to control TurboPi. The installation method is as follows.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>① Make sure all APP permissions are turned on in settings, otherwise APP functions will be limited!</p><p>② Turn on Location and WiFi before operation.</p></section><h3 id="_2-1-1-installation" tabindex="-1">2.1.1 Installation <a class="header-anchor" href="#_2-1-1-installation" aria-label="Permalink to &quot;2.1.1 Installation&quot;">​</a></h3><p><strong><a href="https://play.google.com/store/apps/details?id=com.Wonder.Pi" target="_blank" rel="noreferrer">APP Installation Pack (Android)</a></strong></p><p><strong><a href="https://apps.apple.com/cn/app/wonderpi/id1477946178" target="_blank" rel="noreferrer">APP Installation Pack (iOS)</a></strong></p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li><p>Please turn TurboPi on before connecting.</p></li><li><p>Make sure all APP permissions are turned on in settings, otherwise APP functions will be limited!</p></li><li><p>Turn on Location and WiFi before operation.</p></li></ul></section><h3 id="_2-1-2-app-connection" tabindex="-1">2.1.2 APP Connection <a class="header-anchor" href="#_2-1-2-app-connection" aria-label="Permalink to &quot;2.1.2 APP Connection&quot;">​</a></h3><p>(1) Start robot. (The switch is on Raspberry Pi expansion board). For detailed instruction, please refer to the file in &quot;<strong><a href="https://docs.hiwonder.com/projects/TonyPi/en/latest/docs/1.getting_ready.html#charging-and-power-on-status-description" target="_blank" rel="noreferrer">Getting Ready\\1.3 Charging and Power-On Status Explanation</a></strong>&quot;.</p><p>(2) After TurboPi boots up successfully, it enters AP direct connection mode, and generates a WiFi starting with <strong>&quot;HW&quot;</strong>. Join this WiFi, and then you can experience robot games</p><ul><li><strong>Introduction to Connection Mode</strong></li></ul><p>There are two connection modes, namely direct connection mode and LAN mode. APP functions are the same under these two modes.</p><p>(1) <strong>AP direct connection mode</strong>: RaspberryPi generates a WiFi which can be connected by phones. But this WiFi has no internet access.</p><p>(2) <strong>STA LAN mode</strong>: Raspberry Pi actively connects to specific WiFi. In this mode, you can access internet.</p><ul><li><strong>Direct Connection Mode (MUST-READ)</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>After TurboPi boots up successfully, it enters AP direct connection mode, and generates a WiFi starting with <strong>&quot;HW&quot;</strong>.</p></section><p>(1) Open&quot;<strong>WonderPi</strong>&quot;. Select <strong>&quot;Standard -&gt;TurboPi&quot;</strong> in sequence.</p><img loading="lazy" height="461" width="1000" src="'+g+'"><p>(2) Tap <strong>&quot;+&quot;</strong> in bottom right corner, and then select <strong>Direct Connection Mode</strong>.</p><img loading="lazy" src="'+h+'"><p>(3) Tap <strong>&quot;Go to connect device hotspot&quot;</strong>. Join WiFi starting with &quot;HW&quot;. The password is <strong>&quot;hiwonder&quot;</strong>.</p><img loading="lazy" src="'+p+'"><img loading="lazy" src="'+o+'" style="width:350px;" class="common_img"><p>(4) Return back to APP after connection.</p><img loading="lazy" src="'+n+'" style="width:350px;" class="common_img"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>for iOS user, please don&#39;t return to APP until WiFi icon appears on status bar, otherwise robot cannot be searched. If robot cannot be searched by APP, tap <img loading="lazy" height="52" width="52" src="'+m+'" style="width:45px;"> to refresh.</p></section><p>(5) APP automatically connects to robot. When robot icon below occurs, connection completes.</p><img loading="lazy" height="461" width="1000" src="'+u+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>if you are informed of &quot;<strong>No Internet. Whether to keep connection</strong>&quot;, just select &quot;<strong>keep connected</strong>&quot;.</p></section><p>(6) Tap robot icon to enter mode selection interface.</p><img loading="lazy" height="461" width="1000" src="'+A+'"><p>For detailed introduction to robot games, please refer to the file in &quot;<strong><a href="#anchor_2_2">2.2 APP Control</a></strong>&quot;.</p><ul><li><strong>LAN Connection Mode</strong></li></ul><p>(1) Disconnect the WiFi generated by TurboPi. Connect your phone to a WiFi. Take <strong>&quot;Hiwonder&quot;</strong> as example.</p><img loading="lazy" src="'+b+'" style="width:350px;" class="common_img"><p>(2) After connection, open <strong>&quot;WonderPi&quot;</strong>. Select <strong>&quot;Standard -&gt;TurboPi&quot;</strong> in sequence.</p><img loading="lazy" height="461" width="1000" src="'+f+'"><p>(3) Tap <strong>&quot;+&quot;</strong> in bottom right corner, and then select LAN Mode.</p><img loading="lazy" height="461" width="1000" src="'+y+'"><p>(4) Input the password of the WiFi your phone joins. Ensure the password you input is correct, otherwise APP fails to connect to robot. Tap <strong>&quot;OK&quot;</strong>.</p><img loading="lazy" height="461" width="1000" src="'+P+'"><p>(5) Tap <strong>&quot;Go to connect device hotspot&quot;</strong>.</p><img loading="lazy" height="461" width="1000" src="'+v+'"><p>(6) Join the WiFi starting with <strong>&quot;HW&quot;.</strong> The password is <strong>&quot;hiwonder&quot;</strong>. After connection, return back to APP.</p><p class="common_img" style="text-align:center;"><img loading="lazy" src="'+o+'" style="width:300px;"><img loading="lazy" src="'+n+'" style="width:300px;"></p><p>(7) APP automatically configures network.</p><img loading="lazy" height="461" width="1000" src="'+w+'"><p>(8) After a while, robot icon below occurs, and LED on expansion board keeps on.</p><img loading="lazy" height="461" width="1000" src="'+q+'"><p>(9) Long press robot icon to check TurboPi&#39;s IP and ID.</p><img loading="lazy" height="461" width="1000" src="'+T+'"><p>(10) Tap robot icon to enter mode selection interface.</p><img loading="lazy" height="461" width="1000" src="'+k+'"><p>For detailed introduction to robot games, please refer to the file in&quot;<strong><a href="#anchor_2_2">2.2 APP Control</a></strong>&quot;.</p><p id="anchor_2_2"></p><h2 id="_2-2-app-control" tabindex="-1">2.2 APP Control <a class="header-anchor" href="#_2-2-app-control" aria-label="Permalink to &quot;2.2 APP Control&quot;">​</a></h2><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>This section takes TonyPi Pro as example. The content is also suitable for TonyPi.</p></section><h3 id="_2-2-1-preparation" tabindex="-1">2.2.1 Preparation <a class="header-anchor" href="#_2-2-1-preparation" aria-label="Permalink to &quot;2.2.1 Preparation&quot;">​</a></h3><p>Install APP and connect TonyPi to APP according to the instruction in <a href="#anchor_1">2.1 APP Installation and Connection</a>.</p><h3 id="_2-2-2-experience-robot-games" tabindex="-1">2.2.2 Experience Robot Games <a class="header-anchor" href="#_2-2-2-experience-robot-games" aria-label="Permalink to &quot;2.2.2 Experience Robot Games&quot;">​</a></h3><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p><strong>Hurdle Obstacle Avoidance</strong> and <strong>Go up and down stair</strong> only suitable for TonyPi Pro.</p></section><p>Click the robot icon to enter to the game selection interface.</p><img loading="lazy" height="455" width="1000" class="common_img" src="'+z+'"><ul><li><strong>Model Control</strong></li></ul><p>(1) Click on the icon &quot;<strong>Model Control</strong>&quot; and you will enter the corresponding interface. At the same time, the robot will immediately return to its initial position.</p><img loading="lazy" height="456" class="common_img" src="'+j+'" width="100%"><p>(2) The interface of &quot;Model Control&quot; is divided into two parts. The left side of the interface allows you to control the robot&#39;s movement by sliding the joystick. Other function icons can be referred to in the table below:</p><table tabindex="0"><thead><tr><th>Icon</th><th>Function</th></tr></thead><tbody><tr><td><img loading="lazy" height="135" width="184" src="'+C+'"></td><td>Drag central button to control TonyPi to move.</td></tr><tr><td><img loading="lazy" height="133" width="294" src="'+I+'"></td><td>You can control the robot to move left, move right, or stand straight.</td></tr><tr><td><img loading="lazy" height="187" width="312" src="'+x+'"></td><td>You can execute built-in actions and the function to stand up from a fall.</td></tr></tbody></table><p>The right side of the interface displays the real-time video feed from the camera. You can drag the interface to rotate the camera.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The camera&#39;s head servo is equipped with limit protection. When it reaches the extreme position and you try to slide the screen again, there will be vibration feedback. At this point, please do not continue to rotate it.</p></section><p>(3) To return to the game selection interface, click on a blank area to bring up the title bar, then click on the left triangle on the left side.</p><ul><li><strong>Auto Shooting</strong></li></ul><p>TonyPi can recognize red, green and blue. TonyPi will adjust its position close to the ball and then kick it forward.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li>Please operate in well-lwit indoor, and avoid direct lighting.</li><li>Remove objects in same or similar color to the target, otherwise recognition will be interfered.</li><li>If the recognition effect is not well, you can adjust color threshold according to <a href="#anchor_2_3">2.3 Adjust Color Threshold</a>.</li></ul></section><p>(1) Tap &quot;<strong>Auto Shooting</strong>&quot; icon to enter game interface. The interface is divided into three parts.</p><img loading="lazy" height="452" width="860" class="common_img" src="'+_+'" style="width:100%;"><p>① Status bar.</p><p>② The left side of the interface are the options to activate the game functionalities.</p><p>③ The right side of the interface is the area displaying the camera feed.</p><p>(2) Click &quot;<strong>Start Recognition</strong>&quot; button, you can sequentially place red, blue, and green objects individually in front of the camera. Taking green as an example, when TonyPi recognizes the green object, it will outline the recognized green object in the feedback screen and then approach the ball to kick it away.</p><p>(3) To return to the game selection interface, click on the blank area of the current interface to bring up the title bar, then click <img loading="lazy" height="41" width="41" src="'+t+'"> button.</p><ul><li><strong>Color Recognition</strong></li></ul><p>TonyPi can recognize red, green and blue. When recognizing red, it nods. When recognizing blue or green, it shakes head.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li>Please operate in well-lit indoor, and avoid direct lighting.</li><li>Remove objects in same or similar color to the target, otherwise recognition will be interfered.</li><li>If the recognition effect is not well, you can adjust color threshold according to <a href="#anchor_2_3">2.3 Adjust Color Threshold</a>.</li></ul></section><p>(1) Tap &quot;<strong>Color Recognition</strong>&quot; icon to enter game interface. The interface is divided into three parts.</p><img loading="lazy" height="461" width="861" class="common_img" src="'+Q+'" style="width:100%;"><p>① Status bar.</p><p>② The left side of the interface are the options to activate or deactiave the game functionalities.</p><p>③ Camera returned image.</p><p>(2) Start the game. Then you can put red, green and blue objects in sequence in front of camera. Take green as example. When TonyPi recognizes green, this item will be framed on the camera returned image. At the same time, TonyPi emits a beep, and then &quot;<strong>shakes head</strong>&quot;.</p><table tabindex="0"><thead><tr><th>Color</th><th>Recognition result</th></tr></thead><tbody><tr><td>Red</td><td>Buzzer emits one beep, and camera nods.</td></tr><tr><td>Green</td><td>Buzzer emits one beep, and camera shakes.</td></tr><tr><td>Blue</td><td>Buzzer emits one beep, and camera shakes.</td></tr></tbody></table><p>(3) To return to the game selection interface, click on the blank area of the current interface to bring up the title bar, then click <img loading="lazy" height="41" width="41" src="'+t+'"> button.</p><ul><li><strong>Line Following</strong></li></ul><p>Tap icon to enter game interface. After game starts, TonyPi go forward along black line or red line.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li><p>Please operate in well-lit indoor, and avoid direct lighting.</p></li><li><p>Remove objects in same or similar color to the target, otherwise recognition will be interfered.</p></li><li><p>If the recognition effect is not well, you can adjust color threshold according to <a href="#anchor_2_3">2.3 Adjust Color Threshold</a>.</p></li></ul></section><img loading="lazy" height="461" width="861" class="common_img" src="'+S+'" style="width:100%;"><p>① Status bar.</p><p>② Game control area.</p><p>③ Camera returned image.</p><p>(1) Turn on &quot;<strong>Start following</strong>&quot;. Then select color. TonyPi Pro will go forward along line of specific color.</p><table class="docutils-nobg" border="1"><tbody><tr><td><strong>Icon</strong></td><td><strong>Function</strong></td></tr><tr><td><img loading="lazy" height="62" width="334" src="'+E+'"></td><td>Start/ stop the game</td></tr><tr><td><img loading="lazy" height="213" width="200" src="'+R+'"></td><td>Select line color</td></tr><tr><td><img loading="lazy" height="160" width="201" src="'+W+'"></td><td>Display the color to tracked</td></tr></tbody></table><p>(2) If you want to return back mode selection interface, tap blank area to make status bar pop up, then click on the button.</p><ul><li><strong>Color Tracking</strong></li></ul><p>Tap icon to enter game interface. Once the game is activated, it enables the functionalities for the head servo to move along with the movement of the target.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li><p>Please operate in well-lit indoor, and avoid direct lighting.</p></li><li><p>Remove objects in same or similar color to the target, otherwise recognition will be interfered.</p></li><li><p>If TonyPi cannot recognize color well, you can adjust color threshold according to &quot;<a href="#anchor_2_3">2.3 Adjust Color Threshold</a>&quot;.</p></li></ul></section><img loading="lazy" height="459" width="864" class="common_img" src="'+B+'" style="width:100%;"><p>① Status bar.</p><p>② Game control area.</p><p>③ Camera returned image.</p><p>(1) Click the &quot;<strong>Start Tracking</strong>&quot; button, then select the target color to activate the tracking game. At this point, TonyPi Pro&#39;s camera will follow the movement of the selected color target.</p><table tabindex="0"><thead><tr><th>Ico</th><th>Function</th></tr></thead><tbody><tr><td><img loading="lazy" height="72" width="200" src="'+V+'"></td><td>Activate/deactivate color tracking game</td></tr><tr><td><img loading="lazy" height="271" width="192" src="'+L+'"></td><td>Select the color to track</td></tr><tr><td><img loading="lazy" height="128" width="162" src="'+D+'"></td><td>Display target color information</td></tr></tbody></table><p>(2) To return to the game selection interface, click on the blank area of the current interface to bring up the title bar, then click on the button.</p><ul><li><strong>Face Recognition</strong></li></ul><p>(1) Click the icon to enter the game interface. The camera will move around, and when it detects a face within 1 meter, the robot will wave towards it.</p><img loading="lazy" height="455" width="863" class="common_img" src="'+G+'" style="width:100%;"><p>① Status bar.</p><p>② Face detection control area.</p><p>③ Camera returned image.</p><p>(2) Click the &quot;<strong>Start Recognition</strong>&quot; button, the head servo will move back and forth from left to right.</p><table tabindex="0"><thead><tr><th>Icon</th><th>Function</th></tr></thead><tbody><tr><td><img loading="lazy" height="62" width="213" src="'+i+'"></td><td>Activate/deactivate the game.</td></tr></tbody></table><p>(3) To return to the game selection interface, click on the blank area of the current interface to bring up the title bar, then click on the button <img loading="lazy" height="41" width="41" src="'+t+'">.</p><ul><li><strong>Tag Recognition</strong></li></ul><p>Click the icon to enter the game interface. Once activated, this game allows TonyPi to recognize different QR codes and perform corresponding actions.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li><p>When recognizing a QR code, the distance should not be too close or too far. Typically, a distance of 35cm between the QR code and the camera is optimal.</p></li><li><p>Please perform this in a well-lit indoor environment, but try to avoid direct strong light.</p></li></ul></section><img loading="lazy" height="353" width="644" class="common_img" src="'+O+'" style="width:100%;"><p>① Status bar.</p><p>② QR code control area.</p><p>③ QR code image.</p><p>(1) Click &quot;<strong>Start Recognition</strong>&quot; button and select different QR code. TonyPi will perform different actions when recognized different QR code.</p><table tabindex="0"><thead><tr><th><strong>Icon</strong></th><th>Function</th></tr></thead><tbody><tr><td><img loading="lazy" height="62" width="213" src="'+i+'"></td><td>Activate/Deactivate game</td></tr></tbody></table><p>(2) To return to the game selection interface, click on the blank area of the current interface to bring up the title bar, then click on the button.</p><ul><li><strong>Hurdle Obstacle Avoidance</strong></li></ul><p>Click the button to enter the game interface. The camera will recognize the blue part of the stair and complete the action of crossing over it.</p><img loading="lazy" height="525" width="990" class="common_img" src="'+U+'" style="width:100%;"><p>① Status bar.</p><p>② Game control area.</p><p>③ Camera feed image.</p><p>(1) Click the <strong>&quot;Start Hurdle&quot;</strong> button. TonyPi will step over it and continue moving forward when the hurdle prop is detected.</p><table tabindex="0"><thead><tr><th><strong>Icon</strong></th><th><strong>Function</strong></th></tr></thead><tbody><tr><td><img loading="lazy" height="47" width="199" src="'+a+'"></td><td>Activate/deactivate the game.</td></tr></tbody></table><p>(2) To return to the game selection interface, click on the blank area of the current interface to bring up the title bar, then click on the button.</p><ul><li><strong>Go up and down stair</strong></li></ul><p>(1) Click the button to enter the game interface. The camera will recognize the red part of the step prop and complete the action of going up and down the steps.</p><img loading="lazy" height="526" width="992" class="common_img" src="'+N+'" style="width:100%;"><p>① Status bar.</p><p>② Game control area.</p><p>③ Camera feed image.</p><p>(2) Click <strong>&quot;Start Hurdling&quot;</strong> button. TonyPi will step over it and continue moving forward when the hurdle prop is detected.</p><table tabindex="0"><thead><tr><th><strong>Icon</strong></th><th><strong>Function</strong></th></tr></thead><tbody><tr><td><img loading="lazy" height="47" width="199" src="'+a+'"></td><td>Activate/deactivate the game</td></tr></tbody></table><p>(3) To return to the game selection interface, click on the blank area of the current interface to bring up the title bar, then click on the button.</p><p id="anchor_2_3"></p><h2 id="_2-3-adjust-color-threshold" tabindex="-1">2.3 Adjust Color Threshold <a class="header-anchor" href="#_2-3-adjust-color-threshold" aria-label="Permalink to &quot;2.3 Adjust Color Threshold&quot;">​</a></h2><p>Different light source will have different influence on the colors, which will result in recognition discrepancy. To tackle this problem, you can adjust color threshold via &quot;<strong>WonderPi</strong>&quot; APP.</p><h3 id="_2-3-1-preparation" tabindex="-1">2.3.1 Preparation <a class="header-anchor" href="#_2-3-1-preparation" aria-label="Permalink to &quot;2.3.1 Preparation&quot;">​</a></h3><p>Start TurboPi. Open &quot;<strong>WonderPi</strong>&quot; APP, and connect it to TurboPi. For how to connect robot to APP, operate referring to &quot;<strong><a href="#anchor_1">2.1 APP Installation and Connection </a></strong>&quot;.</p><h3 id="_2-3-2-interface-layout" tabindex="-1">2.3.2 Interface Layout <a class="header-anchor" href="#_2-3-2-interface-layout" aria-label="Permalink to &quot;2.3.2 Interface Layout&quot;">​</a></h3><p>Tap in upper right corner to enter color threshold adjustment interface.</p><img loading="lazy" src="'+Z+'"><img loading="lazy" height="520" width="1100" src="'+F+'"><p>The table below list function of specific icon.</p><table class="docutils-nobg" border="1"><colgroup><col><col></colgroup><tbody><tr><td><strong>Icon</strong></td><td><strong>Function</strong></td></tr><tr><td><img loading="lazy" height="1184" width="1556" src="'+r+'" style="width:300px;"></td><td><p>Processed camera returned image.</p><p>Target object is white, and other area is black.</p></td></tr><tr><td><img loading="lazy" height="1184" width="1556" src="'+r+'" style="width:300px;"></td><td>Raw camera returned image.</td></tr><tr><td><img loading="lazy" height="75" width="346" src="'+Y+'" style="width:200px;"></td><td>Select the color to be adjusted.</td></tr><tr><td><img loading="lazy" height="85" width="346" src="'+H+'" style="width:200px;"><img loading="lazy" height="84" width="346" src="'+M+'" style="width:200px;"></td><td><p>Adjust L component of camera returned image. &quot;L_min&quot; is lower limit and &quot;L_max&quot; is upper limit.</p></td></tr><tr><td><img loading="lazy" height="85" width="346" src="'+J+'" style="width:200px;"><img loading="lazy" height="83" width="346" src="'+K+'" style="width:200px;"></td><td><p>Adjust A component of camera returned image. &quot;a_min&quot; is lower limit and &quot;a_max&quot; is upper limit.</p></td></tr><tr><td><img loading="lazy" height="84" width="346" src="'+X+'" style="width:200px;"><img loading="lazy" height="85" width="346" src="'+$+'" style="width:200px;"></td><td><p>Adjust B component of camera returned image. &quot;b_min&quot; is lower limit and &quot;b_max&quot; is upper limit.</p></td></tr><tr><td><img loading="lazy" height="84" width="162" src="'+tt+'" style="width:200px;"></td><td>Get instruction to check how to adjust color threshold.</td></tr><tr><td><img loading="lazy" height="87" width="144" src="'+et+'" style="width:100px;"></td><td>Save the adjusted color threshold.</td></tr><tr><td><img loading="lazy" height="87" width="87" src="'+ot+'" style="width:60px;"></td><td>Return back to mode selection interface.</td></tr><tr><td><img loading="lazy" height="87" width="86" src="'+nt+'" style="width:60px;"></td><td>Hide navigation bar.</td></tr><tr><td><img loading="lazy" height="86" width="86" src="'+it+'" style="width:60px;"></td><td>Display Hiwonder info.</td></tr></tbody></table><h3 id="_2-3-3-adjust-color-threshold" tabindex="-1">2.3.3 Adjust Color Threshold <a class="header-anchor" href="#_2-3-3-adjust-color-threshold" aria-label="Permalink to &quot;2.3.3 Adjust Color Threshold&quot;">​</a></h3><p>(1) Select color to be adjusted. Take red as example.</p><img loading="lazy" height="517" width="1100" src="'+at+'"><p>(2) Put red object within camera recognition zone. Set L_min, a_min and b_min to 0, and L_max, a_max and b_max to 255.</p><img loading="lazy" height="530" width="1100" src="'+rt+'"><p>(3) Tap &quot;<strong>Instruction</strong>&quot; icon to check how to adjust color threshold.</p><img loading="lazy" height="524" width="1100" src="'+st+'"><img loading="lazy" height="560" width="1213" src="'+lt+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>if you need to close Instruction window, select &quot;<strong>OK</strong>&quot;.</p></section><p>(4) Red approaches &quot;<strong>+a</strong>&quot; zone, so you need to adjust A component.</p><img loading="lazy" height="300" width="300" src="'+ct+'" style="width:300px;" class="common_img"><p>(5) Keep &quot;<strong>a_max</strong>&quot; value the same, and then increase &quot;<strong>a_min</strong>&quot; value till red object turns white and other area is black.</p><img loading="lazy" height="602" width="1280" src="'+dt+'"><p>(6) Adjust &quot;<strong>L</strong>&quot; and &quot;<strong>B</strong>&quot; values. If it belongs to light red, increase L_min. Otherwise, decrease L_max. If it belongs to warm tone, increase B_min. Otherwise, decrease B_max.</p><img loading="lazy" height="602" width="1280" src="'+gt+'"><p>(7) Remember to save the value after adjustment.</p><img loading="lazy" height="602" width="1280" src="'+ht+'">',180)])])}const wt=s(pt,[["render",mt]]);export{vt as __pageData,wt as default};
